  if (key in target) return target[key];
  if (key === 'createLinearGradient' || key === 'createRadialGradient') return () => gradient;
  return (...args) => {
    for (const arg of args) if (typeof arg === 'number') assert.ok(Number.isFinite(arg));
    if (key === 'arc') assert.ok(args[2] >= 0);
    if (key === 'ellipse') assert.ok(args[2] >= 0 && args[3] >= 0);
    drawn++;
  };
}});
const elements = Object.fromEntries(['garden', 'status', 'announcement', 'plant', 'undo', 'save'].map(id => [id, {
  textContent: '', disabled: false,
  addEventListener(type, fn) { handlers.set(`${id}:${type}`, fn); },
  getBoundingClientRect() { return { width: 1280, height: 800, left: 0, top: 0 }; },
  getContext() { return context; },
  toBlob(callback) { callback({ type: 'image/png' }); }
}]));
const raf = new Map();
