const document = {
  hidden: false,
  getElementById(id) { return elements[id]; },
  addEventListener(type, fn) { handlers.set(`document:${type}`, fn); },
  body: { appendChild() {} },
  createElement() { return { click() { downloaded = true; }, remove() {} }; }
};
